/*
	Sacabambaspis // #WCCChallenge Pond Life 22.08.2023
	https://openprocessing.org/sketch/1987401
	#p5js #creativecoding #generativeart 

	Dear Raph and fellow creative coders,

	you just asked for it, here you are.
	During the creation of the sketch no animal was hurt.
	I just draw them from my memory of the nicest moments 
	I remember them, like it was yesterday <3

	If there is a performance issue, deactivate "activateBlur".

	Added some water movement via gradient and water drops as well as 
	water roses. Implementes a very basic mirroring effect for the drops.

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
*/

const activateBlur = true;
const showFPS = false;

let fishs = [];
let drops = [];
let roses = [];
let frate = [];

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	frameRate(30);
	describe("Happy Sacabambaspis moving in a pond with some water roses and rain drops");
	// fishs
	fishs = [];
	for (let i = 0; i < 25; i++) fishs.push(new Sacabambaspis());
	// drops
	drops = [];
	// roses
	roses = [];
	for (let i = 0; i < 25; i++) roses.push(new WRose());
}

function draw() {
	// background(0, 0, 16);
	background("rgb(14,46,79)")

	// gradient water, intermediate state via noise to emulate water movement
	const grdF = noise(frameCount*0.0086);
	const grd = drawingContext.createLinearGradient(0, -100, 0, height+100);
	grd.addColorStop(0, color("rgb(0,57,20)"));
	grd.addColorStop(grdF, "rgb(14,46,79)");
	grd.addColorStop(1, color("rgb(7,33,75)"));
	drawingContext.fillStyle = grd;
	drawingContext.fillRect(0, 0, width, height); 


	// fishs
	fishs = fishs.sort((a, b) => a.s - b.s);
	for (let f of fishs) {
		f.update();
		f.draw();
	}

	// drops
	if (frameCount % 5 === 0) drops.push(new WDrop(random(width), random(height)));
	drops = drops.filter((x) => x.a > -50)
	for (let d of drops) {
		d.update();
		d.show();
	}

	// roses
	for (let r of roses) {
		r.update();
		r.show();
	}

	// fps
	if (showFPS) {
		const fps = round(frameRate());
		frate.push(fps);
		frate.splice(0, frate.length - width)
		stroke(255, 128);
		beginShape()
		for (let i = 0; i < frate.length; i++) {
			vertex(i, frate[i])
		}
		endShape();
		noStroke();
		fill(255)
		text(fps, 0, 10)
	}
}


class Sacabambaspis {
	constructor() {
		this.x = random(width)
		this.y = -random(height)
		this.c = random(30, 60)
		this.s = random(max(width, height)*0.02, max(width, height)*0.1)
		this.vy = this.s / 25;
		this.vx = this.vy / 10 - random(this.vy / 5); 
		this.t = millis() + random(1000, 10000);
	}

	update() {
		this.y += this.vy;
		if (this.y > height * 1.5) {
			this.x = random(width);
			this.y = -random(height*0.5, height * 1.5)
			this.vx = this.vy / 10;
		}
		this.vx += 0.02 * (noise(frameCount * fract(this.vy) * 0.1) - 0.45);
		this.x += this.vx
	}

	draw() {
		let x = this.x, y = this.y, s = this.s, v = this.vy, c = this.c;
		// scale size depending on y
		s *= map(this.y, 0, height, 0.75, 1.25, true);
		const s2 = s * 0.5;
		const s4 = s * 0.25;
		const tailX = (noise(frameCount*0.04536) - 0.5) * s4 - sin(frameCount*v*0.0712513)*s4;
		const anchorY = noise(frameCount*0.084536)

		push();
			translate(x, y)
			let moveVec = createVector(this.vx, this.vy);
			rotate(moveVec.heading() - HALF_PI + (noise(frameCount * 0.01) - 0.5) * v * 0.1);

			colorMode(HSB, 100)
			stroke(c, 35, 40);
			fill(c, 55, 20);
			drawingContext.shadowBlur = activateBlur ? s * noise(frameCount * fract(v) * 0.1) : 0;
			drawingContext.shadowColor = color(c, 35, 40);

			// fin
			push()
			translate(0, -s*0.75+anchorY)
			rotate(sin(frameCount*v*0.0712513)*0.25)
			beginShape();
			vertex(-s, 0);
			bezierVertex(-s2, -s4, s2, -s4, s, 0);
			bezierVertex(s2, s4, -s2, s4, -s, 0);
			endShape();
			pop();

			// body
			ellipse(0, 0, s, s * 0.75) // head
			beginShape();
				vertex(-s2,0);
				bezierVertex(-s2,-s*(2-anchorY), tailX,-s*(4-anchorY), -tailX,-s*4);
				bezierVertex(tailX,-s*(4-anchorY), s2,-s*(2-anchorY), s2,0);
			endShape();

			// shadow on body / end glow body & head
			drawingContext.shadowBlur = 0;
			push()
				noStroke();
				ellipse(0, 0, s-1, s * 0.75 - 1) // head
				fill(c, 10, 100, 5)
				scale(0.5,0.75)
				translate(s4,-s4)
				beginShape();
					vertex(-s2,0);
					bezierVertex(-s2,-s*(2-anchorY), tailX,-s*(4-anchorY), tailX,-s*4);
					bezierVertex(tailX,-s*(4-anchorY), s2,-s*(2-anchorY), s2,0);
					bezierVertex(s4,-s4*0.5, 0,-s4*0.5, -s4,-s4*0.5);
				endShape();
				scale(0.5,0.75)
				translate(s4,-s4)
				beginShape();
					vertex(-s2,0);
					bezierVertex(-s2,-s*(2-anchorY), tailX,-s*(4-anchorY), tailX,-s*4);
					bezierVertex(tailX,-s*(4-anchorY), s2,-s*(2-anchorY), s2,0);
					bezierVertex(s4,-s4*0.5, 0,-s4*0.5, -s4,-s4*0.5);
				endShape();
			pop();

			fill("black");
			noStroke();
			quad(-s4,s4*0.5, 0,s4*0.5-noise(frameCount*0.012)*s4*0.25, s4,s4*0.5, 0,s4)
			// nose
			circle(-s4*0.15,-s4*0.05,s4*0.15);
			circle(s4*0.15,-s4*0.05,s4*0.15);
			// eyes
			const t = this.t - millis();
			const f = t > 1000 || t < 1 ? 1 : constrain(1 - (1000-t)/t, 0.1, 1.5);
			if (t < 1) this.t = millis() + random(2000, 10000);
			ellipse(-s4,-s4*0.25,s4*0.5,s4*0.5*f);
			ellipse(s4,-s4*0.25,s4*0.5,s4*0.5*f);

		pop();
	}
}

class WRose {
	constructor() {
		this.x = random(width)
		this.y = random(height)
		this.s = random(max(width, height) * 0.02, max(width, height) * 0.04);
		this.n = random(0.005, 0.01);
		this.a = 255;
		this.f = random(TWO_PI)
		this.num = floor(random(6, 11));
	}
	update() {
		this.f += this.n;
		this.y -= this.s * this.n; // 0.4;
		if (this.y < -this.s) {
			this.y = height + this.s
			this.x = random(width);
		}
	}
	show() {
		push();

		translate(this.x + noise(frameCount * this.n) * this.s, this.y + noise((frameCount+1) * this.n) * this.s);
		rotate(noise(frameCount * this.n))
		// stroke("darkblue");
		// fill("darkgreen");
		// scale size depending on y
		const s = this.s * map(this.y, 0, height, 0.75, 1.25, true);
		var s2 = s * 0.5;
		const s3 = s * 0.33;
		var s4 = s * 0.25;
		const num = this.num;
		const da = TWO_PI / num;
		colorMode(HSB, 100)
		// stroke(100, 0, 50, 15);
		for (let i = 0; i < num; i++) {
			fill(10 + noise((frameCount+1) * fract(this.n)) * 50, 75, 45);
			stroke(10 + noise((frameCount+1) * fract(this.n)) * 50, 55, 25);
			beginShape();
			vertex(0, 0);
			bezierVertex(-s4,-s3, -s4,-s3*2, 0,-s);
			bezierVertex(s4,-s3*2, s4,-s3, 0,0);
			endShape(CLOSE);
			rotate(da);

		}
		noStroke();
		// flower, size
		let fs = sin(this.f) * 2 * s3;
		if (fs > 0) {
			// fill("darkred")
			// fill((75 + noise((frameCount+1) * fract(this.n)) * 60) % 100, 80, 40);
			fill((75 + fract(this.n*1000) * 50) % 100, 80, 40);
			circle(0, 0, fs);
		}

		pop();
	}
}

class WDrop {
	constructor(x, y) {
		this.x = x;
		this.y = y;
		this.r = 1;
		this.a = 255;
	}
	update() {
		this.r++;
		this.a-=4;
	}
	show() {
		push();

		let snippet = get(this.x-this.r*0.5, this.y-this.r*0.5,this.r, this.r);
		imageMode(CENTER)
		image(snippet, this.x, this.y, this.r * 1.4, this.r * 1.4);

		stroke(160, 192, 255, this.a);
		strokeWeight(map(this.a, 255, 0, 0.25, 5));
		drawingContext.setLineDash([3, 3]);
		noFill();
		ellipse(this.x, this.y, this.r+this.r, this.r+this.r)

		stroke(160, 192, 255, this.a * 0.5);
		if (this.r > 10) ellipse(this.x, this.y, this.r, this.r)

		stroke(160, 192, 255, this.a * 0.25);
		if (this.r > 40) ellipse(this.x, this.y, this.r*0.2, this.r*0.2)

		pop();
	}
}
